import XCTest

final class ExploreTests: XCTestCase {
    func testExplore() throws {
        continueAfterFailure = true
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()
        Thread.sleep(forTimeInterval: 8)
        writeDump(app, "home")

        let fab = app.buttons["composeFAB"]
        if fab.waitForExistence(timeout: 10) {
            fab.tap()
            Thread.sleep(forTimeInterval: 5)
            writeDump(app, "composer")
        } else {
            writeDump(app, "nofab")
        }
    }

    func writeDump(_ app: XCUIApplication, _ name: String) {
        var text = "=== TREE \(name) ===\n"
        text += app.debugDescription
        text += "\n=== BUTTONS ===\n"
        for e in app.buttons.allElementsBoundByAccessibilityElement {
            text += "id='\(e.identifier)' label='\(e.label)' frame=\(e.frame)\n"
        }
        text += "\n=== FIELDS ===\n"
        for e in app.textFields.allElementsBoundByAccessibilityElement {
            text += "textfield id='\(e.identifier)' label='\(e.label)' value='\(String(describing: e.value))'\n"
        }
        for e in app.textViews.allElementsBoundByAccessibilityElement {
            text += "textview id='\(e.identifier)' label='\(e.label)' value='\(String(describing: e.value))'\n"
        }
        let url = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent("dump_\(name).txt")
        try? text.write(to: url, atomically: true, encoding: .utf8)
    }
}

import XCTest

final class ExploreTests: XCTestCase {
    func testOpenComposer() throws {
        continueAfterFailure = true
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()
        Thread.sleep(forTimeInterval: 8)
        let fab = app.coordinate(withNormalizedOffset: CGVector(dx: 0.818, dy: 0.857))
        fab.tap()
        Thread.sleep(forTimeInterval: 5)
        let tree = app.debugDescription
        let url = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent("dump_composer.txt")
        try? tree.write(to: url, atomically: true, encoding: .utf8)
    }
}

